import 'package:flutter/widgets.dart';

import 'generated/app_localizations.dart';
import 'languages.dart';

export 'generated/app_localizations.dart';
export 'languages.dart';

/// Short access to the generated translations:
/// `Text(context.l10n.settingsLanguageTitle)`.
///
/// Keys are the Ionic transloco keys in lowerCamelCase
/// (`settings.language.title` -> `settingsLanguageTitle`). The ARB files are
/// generated by tool/i18n/build_arb.dart – never edit lib/l10n/*.arb by hand.
///
/// Falls back to German when no [AppLocalizations] is in the tree (widget
/// tests with a bare MaterialApp, widgets built outside MaterialApp), so a
/// migrated widget never crashes and German stays the default.
extension AppLocalizationsX on BuildContext {
  AppLocalizations get l10n =>
      Localizations.of<AppLocalizations>(this, AppLocalizations) ??
      _germanFallback;
}

final AppLocalizations _germanFallback =
    lookupAppLocalizations(const Locale(defaultLanguage));

/// Translations without BuildContext (services, static helpers, toasts built
/// outside the widget tree): follows the active UI language.
AppLocalizations get l10nWithoutContext =>
    lookupAppLocalizations(Locale(currentLanguage()));
